using System.Net;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;
using System.IO.Compression;
using NeoForgeServerManager;

static class FeatureChecks
{
    sealed class FakeApi:HttpMessageHandler
    {
        public Dictionary<string,JsonNode> Versions=new();public Dictionary<string,byte[]> Files=new();public bool BadDownload;
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){var u=request.RequestUri!;string path=u.AbsolutePath;object? response=null;
            if(u.Host=="files.test")return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(BadDownload?[0]:Files[path.TrimStart('/')])});
            string[] parts=path.Split('/',StringSplitOptions.RemoveEmptyEntries);if(parts.Length>=3){if(parts[1]=="version_file"){string hash=parts[2];response=Versions.Values.FirstOrDefault(v=>v["files"]![0]!["hashes"]!["sha512"]!.ToString().Equals(hash,StringComparison.OrdinalIgnoreCase));}
                else if(parts[1]=="version")response=Versions.GetValueOrDefault(parts[2]);
                else if(parts[1]=="project"){string id=parts[2];response=parts.Length==4?new JsonArray(Versions.Values.Where(v=>v["project_id"]!.ToString()==id).Select(v=>v.DeepClone()).ToArray()):new JsonObject{["id"]=id,["title"]="모드 "+id,["slug"]=id};}}
            return Task.FromResult(new HttpResponseMessage(response==null?HttpStatusCode.NotFound:HttpStatusCode.OK){Content=new StringContent(response?.ToString()??"{}",Encoding.UTF8,"application/json")});
        }
        public void Add(string id,string version,string? required=null){byte[] bytes=Encoding.UTF8.GetBytes(id+version);Files[version+".jar"]=bytes;Versions[version]=new JsonObject{["id"]=version,["project_id"]=id,["version_number"]=version,["version_type"]="release",["game_versions"]=new JsonArray("1.21.1"),["loaders"]=new JsonArray("neoforge"),["dependencies"]=required==null?new JsonArray():new JsonArray(new JsonObject{["project_id"]=required,["dependency_type"]="required"}),["files"]=new JsonArray(new JsonObject{["primary"]=true,["filename"]=version+".jar",["url"]="https://files.test/"+version+".jar",["hashes"]=new JsonObject{["sha512"]=Convert.ToHexString(SHA512.HashData(bytes))}})};}
    }
    static void Pump(Task task){while(!task.IsCompleted){Application.DoEvents();Thread.Sleep(5);}task.GetAwaiter().GetResult();}
    public static void Run(string root,Action<bool,string> check)
    {
        var p=new Profile{Folder=Path.Combine(root,"dependency-fixture"),Kind="NeoForge",MinecraftVersion="1.21.1"};Directory.CreateDirectory(p.Folder);
        var api=new FakeApi();api.Add("a","a1","b");api.Add("b","b1");using var net=new DownloadClient("",api);var resolver=new ExtensionDependencies(net);var task=resolver.Plan(p,new("a","A","a"));Pump(task);var plan=task.Result;check(plan.Files.Length==2&&plan.CanInstall,"recursive required dependency plan");
        using(var running=new FileStream(Path.Combine(p.Folder,".manager.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){bool blocked=false;try{Pump(resolver.Install(p,plan,new Progress<string>()));}catch(IOException){blocked=true;}check(blocked&&InstalledExtensions.Files(p).Length==0,"running server lock prevents installation");}
        api.BadDownload=true;try{Pump(resolver.Install(p,plan,new Progress<string>()));throw new Exception("should fail");}catch(IOException){}check(InstalledExtensions.Files(p).Length==0,"bad hash leaves no installed partial files");api.BadDownload=false;Pump(resolver.Install(p,plan,new Progress<string>()));check(InstalledExtensions.Files(p).Length==2,"verified dependency files committed together");
        task=resolver.Plan(p,new("a","A","a"));Pump(task);check(task.Result.Files.All(f=>f.Installed)&&!task.Result.CanInstall,"installed dependencies detected by exact release");
        File.Move(Path.Combine(p.Folder,"mods","b1.jar"),Path.Combine(p.Folder,"mods","b1.jar.disabled"));task=resolver.Plan(p,new("a","A","a"));Pump(task);check(task.Result.Conflicts.Length>0,"disabled dependency blocks duplicate installation");
        using(var window=new DependencyWindow("필수 의존성",task.Result,true)){window.Show();Application.DoEvents();using var image=new Bitmap(window.Width,window.Height);window.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(root,"dependency-status.png"));window.Close();}
        var q=new Profile{Folder=Path.Combine(root,"changed"),Kind="NeoForge",MinecraftVersion="1.21.1"};Directory.CreateDirectory(q.Folder);task=resolver.Plan(q,new("a","A","a"));Pump(task);Directory.CreateDirectory(Path.Combine(q.Folder,"mods"));File.WriteAllText(Path.Combine(q.Folder,"mods","new.jar"),"changed");bool refused=false;try{Pump(resolver.Install(q,task.Result,new Progress<string>()));}catch(IOException){refused=true;}check(refused&&InstalledExtensions.Files(q).Length==1,"changed folder invalidates consent plan");
        var preferences=new PalettePreferences();preferences.Favorites.Add("give");preferences.Custom.Add(new("test","테스트","서버","예시","list",Group:"내 명령어"));preferences.Save();var restored=PalettePreferences.Load();check(restored.Favorites.Contains("give")&&restored.Custom.Single().Example=="list","favorites and custom commands persist");
        var give=PaletteCommands.BuiltIn.Single(x=>x.Id=="give");var item=new GiveItem("minecraft:diamond","다이아몬드","Diamond");check(item.Matches("다이아")&&item.Matches("DIAMOND"),"Korean and English item search");check(PaletteCommands.Build(give,"Steve","",16,item)=="give Steve minecraft:diamond 16","selected item builds exact give command");
        bool rejected=false;try{PaletteCommands.Build(give,"Steve\nstop","",1,item);}catch(ArgumentException){rejected=true;}check(rejected,"player command injection rejected");check(!PaletteCommands.Compatible(PaletteCommands.BuiltIn.Single(x=>x.Id=="tick"),"1.19.4"),"version-specific command gated");
        string jar=Path.Combine(root,"items.jar");using(var z=ZipFile.Open(jar,ZipArchiveMode.Create)){void Entry(string name,string text){using var writer=new StreamWriter(z.CreateEntry(name).Open());writer.Write(text);}Entry("assets/minecraft/models/item/diamond.json","{}");Entry("assets/minecraft/lang/en_us.json","{\"item.minecraft.diamond\":\"Diamond\"}");}var items=GiveItemCatalog.Read([jar],"{\"item.minecraft.diamond\":\"다이아몬드\"}");check(items.Length==1&&items[0].Korean=="다이아몬드","item assets and translations map correctly");
        using(var palette=new CommandPaletteWindow(p,()=>false,_=>Task.CompletedTask,()=>"서버 응답 예시",["Steve"],()=>Task.FromResult(items))){palette.Show();Application.DoEvents();using var image=new Bitmap(palette.Width,palette.Height);palette.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(root,"command-palette.png"));palette.Close();}
        using(var button=new ComingSoonButton()){int clicks=0;button.Click+=(_,_)=>clicks++;typeof(ComingSoonButton).GetMethod("OnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(button,[EventArgs.Empty]);check(clicks==0&&!button.TabStop,"coming soon cannot activate");}
        var conflictApi=new FakeApi();conflictApi.Add("a","a1","b");conflictApi.Add("b","b1");conflictApi.Add("c","c1");conflictApi.Versions["a1"]["dependencies"]!.AsArray().Add(new JsonObject{["project_id"]="c",["dependency_type"]="required"});conflictApi.Versions["c1"]["dependencies"]!.AsArray().Add(new JsonObject{["project_id"]="b",["version_id"]="b2",["dependency_type"]="required"});conflictApi.Add("b","b2");using(var conflictNet=new DownloadClient("",conflictApi)){var r=new ExtensionDependencies(conflictNet);var clean=new Profile{Folder=Path.Combine(root,"conflict"),Kind="NeoForge",MinecraftVersion="1.21.1"};Directory.CreateDirectory(clean.Folder);var conflict=r.Plan(clean,new("a","A","a"));Pump(conflict);check(conflict.Result.Conflicts.Length>0,"contradictory pinned dependency versions blocked");}
    }
    public static void Live(string root,Action<bool,string> check){var p=new Profile{Folder=Path.Combine(root,"live-blank"),Kind="NeoForge",MinecraftVersion="1.21.1"};Directory.CreateDirectory(p.Folder);using var net=new DownloadClient();var search=new ModPluginService(net).Search(p,"sophisticated backpacks");Pump(search);var project=search.Result.First(x=>x.Slug=="sophisticated-backpacks");var plan=new ExtensionDependencies(net).Plan(p,project);Pump(plan);check(plan.Result.Files.Length>=2&&plan.Result.Conflicts.Length==0,"live official dependency plan includes core");using(var window=new DependencyWindow("필수 의존성",plan.Result,true)){window.Show();var panel=window.Controls.Cast<Control>().SelectMany(c=>c.Controls.Cast<Control>()).OfType<DependencyListPanel>().Single();var started=System.Diagnostics.Stopwatch.StartNew();PictureBox[] images=panel.Controls.Cast<Control>().SelectMany(c=>c.Controls.Cast<Control>()).OfType<PictureBox>().ToArray();while(images.Any(i=>i.Image==null)&&started.ElapsedMilliseconds<12000){Application.DoEvents();Thread.Sleep(20);}check(images.Length==plan.Result.Files.Length&&images.All(i=>i.Image!=null),"official dependency images load for every row");check(!panel.Controls.OfType<Label>().Any(),"no unrelated explanatory footer in dependency view");using(var bitmap=new Bitmap(window.Width,window.Height)){window.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(root,"dependency-official-images.png"));}window.Close();}var load=GiveItemCatalog.Load(p);Pump(load);check(load.Result.Any(x=>x.Id=="minecraft:diamond"&&x.Matches("다이아")&&x.Matches("diamond")),"live version-specific bilingual catalog");Console.WriteLine("ITEM COUNT: "+load.Result.Length);}
}
